use strict; use warnings; local $/;
my $f = shift; open my $i, '<:raw', $f or die; my $t = <$i>; close $i;
my $old = "- 62 of 62 runs agree in exit status, stdout and stderr, except one number: the peak RSS that `arena_mem` prints\n  (`vmhwm_kb`, 23 424 on Linux and 27 160 on Windows; both pass the 23 000 threshold). It is each kernel's own\n  measurement.\n";
my $new = "- 62 of 62 runs agree in exit status, stdout and stderr, except one number: the peak RSS that `arena_mem` prints\n  (`vmhwm_kb`, 23 424 on Linux and 27 160 on Windows; both pass the 23 000 threshold). Measured cause (2026-11-13):\n  - Windows charges every process about 3.1 MiB of resident memory for the system DLLs it maps (shared with all\n    processes): a PE that only calls `Sleep` has 3 124 KiB resident, 244 KiB private. An idle Lume program has\n    3 260 KiB resident, 300 KiB private: 136 KiB (56 KiB private) above that floor. On Linux the same program has\n    52 KiB resident.\n  - Growth with data is the same: 24 bytes per cons cell on both (2 496 KiB for 100 000 cells on Windows; Linux\n    reports 1 496 KiB there because the kernel updates its RSS counter in batches, and 23 512 KiB for 1 000 000).\n  - A defect found and fixed on the way: every Windows process committed 6 164 KiB at start (the 4 MiB argv block\n    and 1 MiB of stack committed up front). The argv block is now reserved and committed on first touch (three\n    64 KiB parts up front) and the image asks for 64 KiB of stack commit: 1 300 KiB.\n";
my $k = index($t, $old); die "nf" if $k < 0; substr($t, $k, length($old)) = $new;
my $o2 = "Output of `lumec.exe` is byte-identical to the Linux `lumec` on every input tried. The first launch of a freshly built,\nunsigned `.exe` takes about one second more: Windows Defender inspects it before the process starts (later launches\ndo not pay it, and the process lifetime does not include it). Earlier measurements of this section (process\nlifetime as seen from PowerShell) mixed that inspection and the shell's own overhead into the numbers.\n";
my $n2 = "Output of `lumec.exe` is byte-identical to the Linux `lumec` on every input tried. The first launch of a freshly built,\nunsigned `.exe` takes about one second more: Windows Defender inspects it before the process starts (later launches\ndo not pay it). Never time a program started from PowerShell: on a managed machine the security policy inspects\nwhat a script host starts (measured here: 1.5 to 20 s per launch of the same `.exe`, with 0-16 ms of CPU, against\n14-17 ms when a Lume process starts it). Use the Lume launcher (`os_run_capture_timeout`) or `os_monotonic_ns`\ninside the program.\n";
$k = index($t, $o2); die "nf2" if $k < 0; substr($t, $k, length($o2)) = $n2;
open my $o, '>:raw', $f or die; print $o $t; close $o; print "doc updated\n";
